"""The hexagon: Library Loans rules. It knows ports only - no HTTP, no SQL, no argparse."""
from dataclasses import dataclass

from ports import ForStoringLoans


@dataclass
class Loan:
    id: int
    book_id: str
    member_id: str
    returned: bool = False


class LoanError(Exception):
    """Rule violations; each driving adapter translates them (HTTP status, CLI exit code)."""


class BookAlreadyOnLoan(LoanError):
    pass


class LoanLimitReached(LoanError):
    pass


class LoanNotFound(LoanError):
    pass


# implements the driving port ForManagingLoans; depends only on the driven port ForStoringLoans
class LoanService:
    def __init__(self, store: ForStoringLoans, max_active_per_member=3):
        self._store = store  # configurable dependency: the composition root picks the adapter
        self._max = max_active_per_member

    def borrow(self, book_id, member_id):
        if not book_id or not member_id:
            raise ValueError("bookId and memberId are required")
        active = self._store.active()
        if any(loan.book_id == book_id for loan in active):
            raise BookAlreadyOnLoan(f"book {book_id} is already on loan")
        if sum(loan.member_id == member_id for loan in active) >= self._max:
            raise LoanLimitReached(f"member {member_id} already has {self._max} loans")
        return self._store.add(book_id, member_id)

    def get(self, loan_id):
        loan = self._store.get(loan_id)
        if loan is None:
            raise LoanNotFound(f"loan {loan_id} not found")
        return loan

    def give_back(self, loan_id):
        self._store.mark_returned(self.get(loan_id).id)
        return self.get(loan_id)

"""Member aggregate: a member and their loans form ONE consistency boundary.

Every change goes through the root (Member), so the invariants below hold after every method call:
  1. at most max_loans active loans per member
  2. a member never has the same book on loan twice
"""
from dataclasses import dataclass, replace
from datetime import date


class LoanRuleViolation(Exception):
    pass


class LoanLimitReached(LoanRuleViolation):
    pass


class AlreadyBorrowed(LoanRuleViolation):
    pass


class NotBorrowed(LoanRuleViolation):
    pass


@dataclass(frozen=True)
class Loan:  # entity INSIDE the aggregate; frozen, so outside code cannot edit it behind the root's back
    book_id: str
    borrowed_on: date
    returned_on: date | None = None


class Member:  # aggregate root: the only object outside code may hold a reference to
    def __init__(self, member_id, max_loans=3, loans=(), version=0):
        self.member_id = member_id
        self.max_loans = max_loans
        self._loans = list(loans)
        self.version = version  # optimistic concurrency: the repository compares it on save

    @property
    def loans(self):
        return tuple(self._loans)  # read-only view: no member.loans.append(...) bypassing the rules

    @property
    def active_loans(self):
        return tuple(loan for loan in self._loans if loan.returned_on is None)

    def borrow(self, book_id, today: date):
        # invariants are checked here, in one place, before any state changes
        if any(loan.book_id == book_id for loan in self.active_loans):
            raise AlreadyBorrowed(f"member {self.member_id} already has {book_id}")
        if len(self.active_loans) >= self.max_loans:
            raise LoanLimitReached(f"member {self.member_id} already has {self.max_loans} loans")
        loan = Loan(book_id, today)
        self._loans.append(loan)
        return loan

    def give_back(self, book_id, today: date):
        for i, loan in enumerate(self._loans):
            if loan.book_id == book_id and loan.returned_on is None:
                self._loans[i] = replace(loan, returned_on=today)
                return self._loans[i]
        raise NotBorrowed(f"member {self.member_id} has no active loan of {book_id}")

"""Transactional outbox: a loan change and its event are written in ONE SQLite transaction.

A relay (polling publisher) later reads unpublished rows in order and hands them to the bus.
"""
import json
import sqlite3

from events import CHANNEL, new_event

SCHEMA = """
CREATE TABLE IF NOT EXISTS loans (id INTEGER PRIMARY KEY, book_id TEXT NOT NULL, member_id TEXT NOT NULL,
                                  returned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox (seq INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT NOT NULL,
                                   payload TEXT NOT NULL, published_at TEXT);
"""


class BookAlreadyOnLoan(Exception):
    pass


class LoansWithOutbox:
    def __init__(self, path=":memory:"):
        self.db = sqlite3.connect(path, check_same_thread=False)
        self.db.executescript(SCHEMA)

    def borrow(self, book_id, member_id):
        with self.db:  # one transaction: loan row + outbox row, or neither
            if self.db.execute("SELECT 1 FROM loans WHERE book_id = ? AND returned = 0", (book_id,)).fetchone():
                raise BookAlreadyOnLoan(f"book {book_id} is already on loan")
            loan_id = self.db.execute("INSERT INTO loans (book_id, member_id) VALUES (?, ?)",
                                      (book_id, member_id)).lastrowid
            self._record("LoanCreated", loan_id, book_id, member_id)
        return loan_id

    def give_back(self, loan_id):
        with self.db:
            book_id, member_id = self.db.execute("SELECT book_id, member_id FROM loans WHERE id = ? AND returned = 0",
                                                 (loan_id,)).fetchone()
            self.db.execute("UPDATE loans SET returned = 1 WHERE id = ?", (loan_id,))
            self._record("LoanReturned", loan_id, book_id, member_id)

    def _record(self, event_type, loan_id, book_id, member_id):
        event = new_event(event_type, {"loanId": loan_id, "bookId": book_id, "memberId": member_id})
        # outbox: the event is stored, not sent - sending inside the transaction could not be rolled back
        self.db.execute("INSERT INTO outbox (channel, payload) VALUES (?, ?)",
                        (CHANNEL[event_type], json.dumps(event)))

    def pending(self):
        return self.db.execute("SELECT COUNT(*) FROM outbox WHERE published_at IS NULL").fetchone()[0]


class Relay:
    def __init__(self, db, bus):
        self.db, self.bus = db, bus

    def publish_pending(self):
        rows = self.db.execute("SELECT seq, channel, payload FROM outbox WHERE published_at IS NULL "
                               "ORDER BY seq").fetchall()  # order: E1 before E2, as committed
        for seq, channel, payload in rows:
            self.bus.publish(channel, json.loads(payload))
            self._mark_published(seq)  # a crash before this line => the event is sent again (at least once)
        return len(rows)

    def _mark_published(self, seq):
        with self.db:
            self.db.execute("UPDATE outbox SET published_at = datetime('now') WHERE seq = ?", (seq,))
